import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第四册：流利英语 · 全册语法总结 · 过去分词作后置定语至独立主格的主语与分词","description":"按课时归集语法规则、原创例句和易错边界。","frontmatter":{"title":"第四册：流利英语 · 全册语法总结 · 过去分词作后置定语至独立主格的主语与分词","description":"按课时归集语法规则、原创例句和易错边界。","splitFrom":"life/english/new-concept/book-4/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第四册：流利英语 · 全册语法总结","summary":"按课时归集语法规则、原创例句和易错边界。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 全册语法总结 · 过去完成时与过去叙事参照点至同位语从句与定语从句","link":"/life/english/new-concept/book-4/grammar-part-02"},"next":{"text":"第四册：流利英语 · 全册语法总结 · 形容词前置的 as 让步结构至被动语态中的时态与体","link":"/life/english/new-concept/book-4/grammar-part-04"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 全册语法总结 · 过去完成时与过去叙事参照点至同位语从句与定语从句","link":"/life/english/new-concept/book-4/grammar-part-02"},"next":{"text":"第四册：流利英语 · 全册语法总结 · 形容词前置的 as 让步结构至被动语态中的时态与体","link":"/life/english/new-concept/book-4/grammar-part-04"}},"headers":[],"relativePath":"life/english/new-concept/book-4/grammar-part-03.md","filePath":"life/english/new-concept/book-4/grammar-part-03.md"}'),s={name:"life/english/new-concept/book-4/grammar-part-03.md"};function r(i,e,h,l,p,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第四册-流利英语-·-全册语法总结-·-过去分词作后置定语至独立主格的主语与分词" tabindex="-1">第四册：流利英语 · 全册语法总结 · 过去分词作后置定语至独立主格的主语与分词 <a class="header-anchor" href="#第四册-流利英语-·-全册语法总结-·-过去分词作后置定语至独立主格的主语与分词" aria-label="Permalink to &quot;第四册：流利英语 · 全册语法总结 · 过去分词作后置定语至独立主格的主语与分词&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-4/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-4/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-4/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-4/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-4/review">综合复习与自测</a></p><h2 id="过去分词作后置定语" tabindex="-1">过去分词作后置定语 <a class="header-anchor" href="#过去分词作后置定语" aria-label="Permalink to &quot;过去分词作后置定语 {#过去分词作后置定语}&quot;">​</a></h2><p>名词 + 过去分词短语通常可展开为被动关系从句：samples collected yesterday 等于 samples that were collected yesterday。过去分词不必总表示过去时间，关键是与名词的被动关系；the methods used today 也可指现在。现在分词通常表达主动或进行关系。写作时要清楚谁执行动作，避免把 substances producing an effect 与 substances produced in a laboratory 混淆。</p><p><strong>L20 原创例句：</strong> The samples collected on Tuesday were analysed separately.</p><p>周二采集的样本被分别分析。</p><p><strong>易错：</strong> 不要把 collected 当成全句唯一谓语而漏掉 were analysed；该短语只限定样本。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-020">Lesson 20</a></p><h2 id="it-is-was-that-强调句" tabindex="-1">It is/was…that 强调句 <a class="header-anchor" href="#it-is-was-that-强调句" aria-label="Permalink to &quot;It is/was…that 强调句 {#it-is-was-that-强调句}&quot;">​</a></h2><p>强调句用 It is/was + 被强调部分 + that/who + 其余成分，常强调主语、宾语或状语。It was the lighting that changed the scene. 去掉 It was 与 that 后可还原 The lighting changed the scene。不要把所有 it is…that 都当强调句：It is clear that… 中 it 是形式主语，clear 不能作为原句成分还原。强调时间通常仍用 that，而不是 when。</p><p><strong>L21 原创例句：</strong> It was the actor’s silence that made the final scene so tense.</p><p>正是演员的沉默让最后一幕如此紧张。</p><p><strong>易错：</strong> It was in 1910 when… 若意在强调时间，应使用 that；when 另可引导关系或时间从句。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-021">Lesson 21</a></p><h2 id="what-从句作主语与表语" tabindex="-1">what 从句作主语与表语 <a class="header-anchor" href="#what-从句作主语与表语" aria-label="Permalink to &quot;what 从句作主语与表语 {#what-从句作主语与表语}&quot;">​</a></h2><p>what 从句相当于 the thing(s) that，内部的 what 同时承担从句成分。What matters is how the knowledge is used. 中 what 作 matters 的主语，整个从句作主句主语。that 内容从句中的 that 通常不充当从句成分，因此不可随意互换。what 从句作主语时谓语往往用单数；若语义明确指多个事物，实际一致关系需看整体结构，初学写作宜使用清晰单数表达。</p><p><strong>L22 原创例句：</strong> What matters is whether the new tool solves a real problem.</p><p>重要的是新工具是否解决了一个真实问题。</p><p><strong>易错：</strong> That matters is… 不能替代 What matters is…；what 在从句中还承担 matters 的主语。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-022">Lesson 22</a></p><h2 id="现在分词状语与逻辑主语" tabindex="-1">现在分词状语与逻辑主语 <a class="header-anchor" href="#现在分词状语与逻辑主语" aria-label="Permalink to &quot;现在分词状语与逻辑主语 {#现在分词状语与逻辑主语}&quot;">​</a></h2><p>现在分词短语可表示同时动作、方式或伴随，通常与主句主语共享动作执行者。Gliding above the lake, the bird changed direction. 中 gliding 的执行者是 bird。若写 Gliding above the lake, the wind grew stronger，就错误地让 wind 执行滑翔动作，形成悬垂修饰。分词不独立标明时态，时间关系由主句和语境确定；需要明确不同主语时改用完整从句。</p><p><strong>L23 原创例句：</strong> Gliding above the field, the bird turned towards the hills.</p><p>鸟在田野上方滑翔着，转向了群山。</p><p><strong>易错：</strong> Watching the bird, its wings looked wide 错把 wings 当观察者；可改为 As I watched the bird, its wings looked wide。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-023">Lesson 23</a></p><h2 id="否定或限制副词前置倒装" tabindex="-1">否定或限制副词前置倒装 <a class="header-anchor" href="#否定或限制副词前置倒装" aria-label="Permalink to &quot;否定或限制副词前置倒装 {#否定或限制副词前置倒装}&quot;">​</a></h2><p>Never、rarely、seldom、not until 等放在句首强调时，主句通常采用助动词在主语之前的部分倒装：Rarely do we agree on every detail。原句没有助动词时根据时态添加 do/does/did，实义动词恢复原形。Not until 引导时间短语或从句时，倒装发生在后面的主句，而不是 until 从句。倒装增加修辞强调，日常说明无需句句使用。</p><p><strong>L24 原创例句：</strong> Rarely do two viewers notice exactly the same details in a painting.</p><p>两位观者很少会注意到一幅画中完全相同的细节。</p><p><strong>易错：</strong> Rarely two viewers notice… 缺倒装；Rarely do two viewers notices… 又错误地给实义动词加 s。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-024">Lesson 24</a></p><h2 id="名词化与施事信息" tabindex="-1">名词化与施事信息 <a class="header-anchor" href="#名词化与施事信息" aria-label="Permalink to &quot;名词化与施事信息 {#名词化与施事信息}&quot;">​</a></h2><p>名词化把动词或形容词转为名词表达，例如 people concentrate → concentration。它便于讨论抽象过程，但可能隐藏谁做了什么：a reduction in errors 没有说明谁减少了错误，也不说明原因。介词选择应随搭配，如 exposure to noise、an increase in interruptions。改写时保留时间、对象与证据强度，不能把 may affect 改成 the effect of 就暗中确认影响已存在。</p><p><strong>L25 原创例句：</strong> A reduction in background noise coincided with fewer interruptions during the task.</p><p>背景噪声的减少与任务过程中打断次数的下降同时出现。</p><p><strong>易错：</strong> exposure of noise 应改 exposure to noise；coincided with 也不能自动替换为 caused。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-025">Lesson 25</a></p><h2 id="完成式分词状语" tabindex="-1">完成式分词状语 <a class="header-anchor" href="#完成式分词状语" aria-label="Permalink to &quot;完成式分词状语 {#完成式分词状语}&quot;">​</a></h2><p>Having examined the layers, the team proposed a sequence. 中 having done 表示检查发生在提出之前，并与主句共享主语。若对象被检查，可用 having been examined，但要确保逻辑主语是被检查物。完成式分词突出先完成某事再做另一事，不必对所有有先后顺序的动作都使用。主语不一致时，用 after 引导完整从句更清楚，避免因压缩而造成悬垂修饰。</p><p><strong>L26 原创例句：</strong> Having compared the layers, the researchers proposed a tentative sequence of events.</p><p>比较地层之后，研究者提出了一个暂定的事件顺序。</p><p><strong>易错：</strong> Having compared the layers, a sequence was proposed 容易让 sequence 成为比较者；应明确主语 researchers。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-026">Lesson 26</a></p><h2 id="第三条件句与过去反事实" tabindex="-1">第三条件句与过去反事实 <a class="header-anchor" href="#第三条件句与过去反事实" aria-label="Permalink to &quot;第三条件句与过去反事实 {#第三条件句与过去反事实}&quot;">​</a></h2><p>If + had done，主句 would/could/might have done 用来设想已经过去的情形。If the team had checked the balance, they might have noticed the problem. 并不表示检查实际发生了。would have 通常把结果说得较确定，might have 更适合不确定的历史推测。不能把 if 从句写成 if would have checked。除非有明确时间转换，不要把过去条件与现在结果形式随意混用。</p><p><strong>L27 原创例句：</strong> If the model had been tested earlier, the designers might have noticed the imbalance.</p><p>如果模型更早接受了测试，设计者可能会注意到不平衡。</p><p><strong>易错：</strong> If the model would have been tested 错把结果形式放入条件；应写 had been tested。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-027">Lesson 27</a></p><h2 id="间接问句与疑问语序" tabindex="-1">间接问句与疑问语序 <a class="header-anchor" href="#间接问句与疑问语序" aria-label="Permalink to &quot;间接问句与疑问语序 {#间接问句与疑问语序}&quot;">​</a></h2><p>Could you explain what the term means? 中 what 从句是 explain 的宾语，使用 the term means 的陈述语序，不保留直接问句 What does the term mean? 的 does。yes/no 问题可用 whether 或 if 引入。礼貌框架 Could you tell me 不会自动把从句变成过去时；从句时态应由所问内容决定。避免把礼貌间接问句写成多个问号或重复助动词。</p><p><strong>L28 原创例句：</strong> Could you explain what this term means in plain language?</p><p>您能用浅显的语言解释这个术语的含义吗？</p><p><strong>易错：</strong> Could you explain what does this term mean? 错用直接问句语序；应去 does 并用 means。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-028">Lesson 28</a></p><h2 id="使役与许可结构" tabindex="-1">使役与许可结构 <a class="header-anchor" href="#使役与许可结构" aria-label="Permalink to &quot;使役与许可结构 {#使役与许可结构}&quot;">​</a></h2><p>enable/allow + 宾语 + to do 表示使某人能够或允许某人做事；make + 宾语 + 动词原形表示使某人做事，主动结构不带 to。被动 be made to do 则恢复 to。The cushion allows the craft to move… 描述功能，不能写 allows the craft move。enable 强调能力或条件，allow 可表许可也可表条件允许；实际语义要结合装置或人的语境判断。</p><p><strong>L29 原创例句：</strong> The air cushion allows the model to move across the smooth floor.</p><p>气垫使这个模型能够在光滑地板上移动。</p><p><strong>易错：</strong> allows the model move 缺少 to；不要把 allow 的结构误套成 make 的结构。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-029">Lesson 29</a></p><h2 id="介词-which-的关系从句" tabindex="-1">介词 + which 的关系从句 <a class="header-anchor" href="#介词-which-的关系从句" aria-label="Permalink to &quot;介词 + which 的关系从句 {#介词-which-的关系从句}&quot;">​</a></h2><p>the depth at which the instrument operates 中 which 指 depth，at 来自 operate at a depth。正式表达可把介词放在关系代词前；较口语的限制性从句可把介词放句尾，如 the depth which it operates at。介词后的关系代词不能用 that，也不能省略。选择介词应看动词或名词搭配，不能见到地点就一律用 in；pressure 常搭配 under。</p><p><strong>L30 原创例句：</strong> The pressure under which the sensor operates must be recorded.</p><p>必须记录传感器工作时所处的压力。</p><p><strong>易错：</strong> under that the sensor operates 不成立；介词前置的关系结构用 which。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-030">Lesson 30</a></p><h2 id="独立主格的主语与分词" tabindex="-1">独立主格的主语与分词 <a class="header-anchor" href="#独立主格的主语与分词" aria-label="Permalink to &quot;独立主格的主语与分词 {#独立主格的主语与分词}&quot;">​</a></h2><p>独立主格结构有自己的名词或代词逻辑主语，如 The clay still wet, the artist covered the model。它可补充时间、原因或伴随背景，不必与主句主语一致。名词后可接分词、形容词或介词短语。与普通分词状语不同，Materials prepared, we began 中 prepared 的承受者是 materials。正式写作中应避免连续堆叠；背景关系可能含糊时，用 because 或 after 完整从句更清楚。</p><p><strong>L31 原创例句：</strong> The clay still damp, the sculptor covered the model before leaving.</p><p>黏土还湿着，雕塑家离开前盖住了模型。</p><p><strong>易错：</strong> 不要把独立主格误写成 The clay was still damp, the sculptor covered…；两个完整句不能仅用逗号连接。</p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-031">Lesson 31</a></p>',75)])])}const m=a(s,[["render",r]]);export{g as __pageData,m as default};
